input.command:
node -e '
const fs=require("fs");
let t=fs.readFileSync("tsconfig.json","utf8");
t=t.replace(`"compilerOptions": {`,`"compilerOptions": {\n    "strict": true,`)
 .replace(`"angularCompilerOptions": {`,`"angularCompilerOptions": {\n    "strictTemplates": true,`);
fs.writeFileSync("tsconfig.json",t);
const p=JSON.parse(fs.readFileSync("package.json","utf8"));
Object.assign(p.scripts,{"typecheck":"tsc -p tsconfig.app.json --noEmit && tsc -p tsconfig.spec.json --noEmit","test":"ng test --watch=false","e2e":"playwright test","verify":"npm run lint && npm run typecheck && npm test"});
fs.writeFileSync("package.json",JSON.stringify(p,null,2)+"\n");
'
mkdir -p e2e
cat > playwright.config.ts <<'EOF'
import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './e2e',
  fullyParallel: true,
  retries: process.env['CI'] ? 1 : 0,
  use: {
    baseURL: process.env['E2E_BASE_URL'] ?? 'http://localhost:4200',
    trace: 'on-first-retry',
  },
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],
  webServer: process.env['E2E_BASE_URL']
    ? undefined
    : { command: 'npm start', url: 'http://localhost:4200', reuseExistingServer: true },
});
EOF
cat > e2e/smoke.spec.ts <<'EOF'
import { expect, test } from '@playwright/test';

test('app shell loads', async ({ page }) => {
  await page.goto('/');
  await expect(page).toHaveTitle(/Frontend/i);
});
EOF
grep -n "playwright\|test-results" .gitignore || printf "\n# Playwright\n/test-results/\n/playwright-report/\n" >> .gitignore
npm run verify 2>&1 | tail -15

