(() => {
const out = {title: document.title, url: location.href};
const cs = el => el ? getComputedStyle(el) : null;
const pick = (sel) => { const el = document.querySelector(sel); if(!el) return null; const s = cs(el); return {sel, font: s.fontFamily, size: s.fontSize, weight: s.fontWeight, color: s.color, bg: s.backgroundColor, lh: s.lineHeight, radius: s.borderRadius}; };
out.typo = ['body','h1','h2','h3','h4','p','a','button','.btn','nav a','footer'].map(pick).filter(Boolean);
// css vars on root
const vars = {}; for (const sh of document.styleSheets) { try { for (const r of sh.cssRules) { if (r.selectorText === ':root') { for (const p of r.style) if (p.startsWith('--')) vars[p] = r.style.getPropertyValue(p).trim(); } } } catch(e){} }
out.vars = Object.fromEntries(Object.entries(vars).slice(0,120));
// color frequency
const freq = {}; document.querySelectorAll('body *').forEach(el => { const s = cs(el); for (const k of ['color','backgroundColor','borderTopColor']) { const v = s[k]; if (v && v!=='rgba(0, 0, 0, 0)') freq[k+':'+v]=(freq[k+':'+v]||0)+1; } });
out.colors = Object.entries(freq).sort((a,b)=>b[1]-a[1]).slice(0,40);
const fonts = {}; document.querySelectorAll('body *').forEach(el=>{const f=cs(el).fontFamily; fonts[f]=(fonts[f]||0)+1}); out.fonts = fonts;
out.fontFaces = [...document.fonts].map(f=>f.family+' '+f.weight+' '+f.style+' '+f.status).filter((v,i,a)=>a.indexOf(v)===i).slice(0,40);
out.logos = [...document.querySelectorAll('img,svg')].filter(e=>/logo/i.test((e.getAttribute('src')||'')+(e.getAttribute('alt')||'')+(e.className?.baseVal??e.className)+(e.id||''))).map(e=>({tag:e.tagName, src:e.getAttribute('src'), alt:e.getAttribute('alt')})).slice(0,10);
out.imgs = [...document.querySelectorAll('img')].slice(0,30).map(i=>({src:i.currentSrc||i.src, alt:i.alt, w:i.naturalWidth,h:i.naturalHeight}));
out.links = [...new Set([...document.querySelectorAll('a[href]')].map(a=>a.href))].slice(0,80);
return out;
})()

