input.text:
window.__extract = () => {
const out = {title: document.title, url: location.href};
const cs = el => getComputedStyle(el);
const pick = (sel) => { const el = document.querySelector(sel); if(!el) return null; const s = cs(el); return {sel, font: s.fontFamily.slice(0,60), size: s.fontSize, weight: s.fontWeight, color: s.color, bg: s.backgroundColor, lh: s.lineHeight, radius: s.borderRadius, pad: s.padding, tt: s.textTransform}; };
out.typo = ['body','h1','h2','h3','h4','p','button','a[class*=btn],a[class*=button],button[class*=btn]','input','label','[class*=card]'].map(pick).filter(Boolean);
const freq = {}; document.querySelectorAll('body *').forEach(el => { const s = cs(el); for (const k of ['color','backgroundColor']) { const v = s[k]; if (v && v!=='rgba(0, 0, 0, 0)') freq[k+':'+v]=(freq[k+':'+v]||0)+1; } });
out.colors = Object.entries(freq).sort((a,b)=>b[1]-a[1]).slice(0,25).map(([k,v])=>k+' x'+v);
const fonts = {}; document.querySelectorAll('body *').forEach(el=>{const f=cs(el).fontFamily.split(',')[0]; fonts[f]=(fonts[f]||0)+1}); out.fonts = fonts;
const vars = {}; const rs = getComputedStyle(document.documentElement); for (const sh of document.styleSheets) { try { for (const r of sh.cssRules) { if (r.selectorText && /:root|html|body/.test(r.selectorText) && r.style) { for (const p of r.style) if (p.startsWith('--') && !p.startsWith('--wp')) vars[p] = r.style.getPropertyValue(p).trim(); } } } catch(e){} }
out.vars = Object.fromEntries(Object.entries(vars).slice(0,150));
const radii = {}; document.querySelectorAll('button, a, [class*=card], input, img').forEach(el=>{const r=cs(el).borderRadius; if(r!=='0px') radii[r]=(radii[r]||0)+1}); out.radii = radii;
const shadows = {}; document.querySelectorAll('body *').forEach(el=>{const r=cs(el).boxShadow; if(r!=='none') shadows[r]=(shadows[r]||0)+1}); out.shadows = Object.entries(shadows).slice(0,8);
out.logos = [...document.querySelectorAll('img,svg')].filter(e=>/logo/i.test((e.getAttribute('src')||'')+(e.getAttribute('alt')||'')+(e.getAttribute('class')||'')+(e.id||''))).map(e=>({tag:e.tagName, src:e.getAttribute('src'), alt:e.getAttribute('alt')})).slice(0,6);
out.imgs = [...document.querySelectorAll('img')].filter(i=>i.naturalWidth>300).slice(0,12).map(i=>({src:i.currentSrc||i.src, alt:i.alt}));
out.autoLinks = [...new Set([...document.querySelectorAll('a[href]')].map(a=>a.href).filter(h=>/auto|vehic|carro|movilidad|cotiz/i.test(h)))].slice(0,20);
return out;
}; __extract()

